If you'd like to check it without trusting me, this simulates 1,000 requests:

```javascript
// Simulate 1,000 requests where 90% are cache hits (5 ms) and 10% are misses (200 ms)
// so we can measure the real average instead of reasoning about it
function simulateAverageLatency() {
    const totalRequests = 1000;
    const cacheHitTime = 5;
    const cacheMissTime = 200;
    let totalTime = 0;

    // Every 10th request is a miss, giving exactly 10% misses and 90% hits
    for (let requestNumber = 0; requestNumber < totalRequests; requestNumber++) {
        if (requestNumber % 10 === 0) {
            totalTime = totalTime + cacheMissTime;
        } else {
            totalTime = totalTime + cacheHitTime;
        }
    }

    return totalTime / totalRequests;
}

console.log(simulateAverageLatency()); // prints 24.5
```

